_choice_import_source() {
    printf '%s\n' gemini claude
}

_choice_mcp() {
    agy mcp list 2>/dev/null | gawk 'NR == 1 { next } NF && $1 != "No" { print $1 }'
}

_choice_mcp_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_model() {
    _argc_util_cache 3600 _helper_model_uncached "agy:models"
}

_choice_plugin() {
    local out
    out="$(agy plugin list --json 2>/dev/null)" || return 0
    printf '%s\n' "$out" | jq -b -r '
        if type == "array" then .[]
        elif type == "object" then (.plugins // .items // .[])
        else empty end
        | if type == "string" then .
          elif type == "object" then (.name // .id // .pluginName // .plugin // empty)
          else empty end
        | strings
    ' 2>/dev/null
}

_helper_model_uncached() {
    agy models 2>/dev/null | gawk '
        /Fetching available models/ || /^Error/ || /sign in/ || /^ID[[:space:]]/ || /^NAME[[:space:]]/ { next }
        {
            token = $1
            gsub(/^[[:punct:]]+|[[:punct:]]+$/, "", token)
            if (token ~ /^[a-z][a-z0-9._@+:-]*$/ && length(token) > 2) print token
        }
    '
}
